import{_ as e,o as t,c as s,a2 as n}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"ring-3 应用 - 总览","description":"","frontmatter":{},"headers":[],"relativePath":"zh/l1/overview.md","filePath":"zh/l1/overview.md"}'),o={name:"zh/l1/overview.md"};function d(i,a,l,c,r,p){return t(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="ring-3-应用-总览" tabindex="-1">ring-3 应用 - 总览 <a class="header-anchor" href="#ring-3-应用-总览" aria-label="Permalink to &quot;ring-3 应用 - 总览&quot;">​</a></h1><p>L0 是一个纯服务内核：它以启动 <code>ush</code>（ring-3 shell）完成启动， 而每条用户可见的命令本身就是一个 ring-3 程序。这套架构的全部 要点在于：L0 暴露的表面小、编号化且完备 - 这样应用才能存在。</p><h2 id="分层" tabindex="-1">分层 <a class="header-anchor" href="#分层" aria-label="Permalink to &quot;分层&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>L1  ush (the boot shell) + 284 registry programs</span></span>
<span class="line"><span>    in ocos/l1apps/&lt;name&gt;/main.c - freestanding C against</span></span>
<span class="line"><span>    ocos/interface/*.h</span></span>
<span class="line"><span>     |</span></span>
<span class="line"><span>    SYS_L1SVC(cat, op, arg, out, cap)   20 categories, ~245 ops</span></span>
<span class="line"><span>    SYS_* (open/read/write/fork/execve/wait4/readline/getch/...)</span></span>
<span class="line"><span>     |</span></span>
<span class="line"><span>L0  Open Cube OS service kernel</span></span>
<span class="line"><span>    (ocos/kernel + ocos/services + ocos/drivers)</span></span></code></pre></div><h2 id="表面住在哪里" tabindex="-1">表面住在哪里 <a class="header-anchor" href="#表面住在哪里" aria-label="Permalink to &quot;表面住在哪里&quot;">​</a></h2><table tabindex="0"><thead><tr><th>头文件（ocos/interface/）</th><th>覆盖内容</th></tr></thead><tbody><tr><td><code>l1_api_syscall.h</code></td><td>系统调用包装、字符串/IO 辅助、<code>l1svc_main()</code> - 逐字的服务包装体</td></tr><tr><td><code>l1_svc_ops.h</code></td><td>类别/操作编号契约（从 L0 头文件自动镜像）</td></tr><tr><td><code>l1_i18n_api.h</code></td><td><code>tr_()</code> + 每应用双语表</td></tr><tr><td><code>l1_wizard_api.h</code></td><td>共享向导原语（菜单、询问、确认、锚点探测）</td></tr><tr><td><code>l1_fs_api.h</code></td><td>文件工具共享的路径辅助</td></tr><tr><td><code>l1_editor_core.h</code></td><td><code>edit</code> 与 TUI 编辑器背后的编辑器引擎</td></tr><tr><td><code>l1_i18n_res.h</code></td><td>共享的 <code>MSG_ID</code> 系统消息编号（L0/L1 通用）</td></tr><tr><td><code>l1_diag_cmds.h</code></td><td>共享的 <code>dev</code>/<code>drv</code> 诊断命令层</td></tr><tr><td><code>l1_api_surface.h</code></td><td>伞形头：&quot;L1 能看见什么&quot;的审计点</td></tr><tr><td><code>l1_crt_entry.asm</code></td><td>被链接（而非 include）的 <code>_start</code> 跳板</td></tr></tbody></table><p>服务侧声明住在 <code>ocos/services/*/interface/</code>（每个侧面一个 文件夹）；编号镜像用 <code>tools/gen_l1svc_ops.py</code> 重新生成。</p><h2 id="关键数字" tabindex="-1">关键数字 <a class="header-anchor" href="#关键数字" aria-label="Permalink to &quot;关键数字&quot;">​</a></h2><ul><li><strong>284 个注册表程序</strong> - 276 个历史命令（接口冻结下限；命令 只增不减）加上 8 个合并的大应用。</li><li><strong>20 个 L1SVC 类别</strong>（time/block/nic/snd/power/ota/fs/net/ health/klog/watchdog/crypto/l1/display/input/camera/usb/ocire/ diag/tui），约 245 个编号操作。</li><li>每个程序都附带 <code>i18n/{en,zh}.json</code> - 缺资源则构建失败 （一个没有翻译的程序是交付违规，不是警告）。</li></ul><h2 id="一条命令如何运行" tabindex="-1">一条命令如何运行 <a class="header-anchor" href="#一条命令如何运行" aria-label="Permalink to &quot;一条命令如何运行&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; disk-tool lsblk</span></span>
<span class="line"><span>  ush forks; child execve(&quot;disk-tool&quot;, [&quot;disk-tool&quot;,&quot;lsblk&quot;])</span></span>
<span class="line"><span>  app_main(argc, argv) sees argv[1] = &quot;lsblk&quot;</span></span>
<span class="line"><span>  -&gt; classic dispatch: table lookup -&gt; sys_l1svc(BLOCK, LSBLK, ...)</span></span>
<span class="line"><span>  -&gt; service output printed verbatim</span></span>
<span class="line"><span>  ush wait4()s the child, prints the next prompt</span></span></code></pre></div><p>历史单命令是同一机制再简单一层：<code>lsblk/main.c</code> 就是 <code>l1svc_main(argc, argv, CAT, OP)</code> - 与 v2.2.0 的 ush SVC runner 语义逐字节相同。</p><h2 id="阅读顺序" tabindex="-1">阅读顺序 <a class="header-anchor" href="#阅读顺序" aria-label="Permalink to &quot;阅读顺序&quot;">​</a></h2><ol><li>本页。</li><li><a href="./surface-map.html">surface-map.md</a> - 按组分类的类别/操作。</li><li><a href="./app-anatomy.html">app-anatomy</a> - main.c 由什么构成。</li><li><a href="./writing-apps.html">writing-apps</a> - 一个完整应用，从源码到 <code>run</code>。</li><li>各家族页：驱动、OTA、加载器、TUI、看门狗/健康。</li></ol>`,14)])])}const _=e(o,[["render",d]]);export{u as __pageData,_ as default};
